/**
 * The types `save/cards/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CardSaveRow, CardPresetSlotRow, CardsSaveExtract, CardDrawPoolSaveRow, CardDrawOddsSaveExtract
 * depends    src/mechanics/cards/types
 * used by    src/save/cards/draw-odds, src/save/cards/index, src/save/cards/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { CardDrawOdds } from '../../mechanics/cards/types'

// from read.ts

export interface CardSaveRow {
  index: number
  slug: string | null
  name: string | null
  level: number
  count: number
  unlocked: boolean
  active: boolean
  masteryUnlocked: boolean
}

export interface CardPresetSlotRow {
  presetIndex: number
  slotIndex: number
  cardIndex: number | null
  card: CardSaveRow | null
}

export interface CardsSaveExtract {
  slotsUnlocked: number | null
  cardsBoughtTotal: number | null
  currentPreset: number | null
  presetNames: string[]
  cards: CardSaveRow[]
  equippedCards: CardSaveRow[]
  presetSlots: CardPresetSlotRow[]
  warnings: string[]
}

// from draw-odds.ts

/** One card in the pull pool, as a save decides it. */
export interface CardDrawPoolSaveRow {
  /** The card's id in `CARD_TEMPLATES`. */
  card: string
  name: string
  rarity: 'common' | 'rare' | 'epic'
  level: number
  /** Not milestone-gated, or its milestone claimed, or already owned. */
  inPool: boolean
  /** In the pool and below level 7. */
  drawable: boolean
  /** The milestone that adds this card to the pool, for the six gated cards. */
  gatedBy: { tier: number, wave: number } | null
}

export interface CardDrawOddsSaveExtract {
  pool: CardDrawPoolSaveRow[]
  odds: CardDrawOdds
  warnings: string[]
}
